Voici un exemple de code pour un bot Discord avec la commande de bannissement, construit à l'aide de Discord.js v14 :

1. Installez les dépendances :

```bash
npm install discord.js
npm install dotenv
```

2. Créez un fichier `.env` et ajoutez votre clé de bot Discord :

```
DISCORD_TOKEN=<votre-clé-de-bot-Discord>
```

3. Créez un nouveau fichier JavaScript, par exemple, `index.js`, et copiez-y le code suivant :

```javascript
const { Client, GatewayIntentBits, PermissionsBitField } = require("discord.js");

// Importez les dépendances dotenv pour lire les variables d'environnement
require("dotenv").config();

// Connexion au Discord
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Chargez les commandes
const { SlashCommandBuilder, ActionRowBuilder, ButtonBuilder, ButtonStyle } = require("discord.js");

// Commande de bannissement
const banCommand = new SlashCommandBuilder()
  .setName("ban")
  .setDescription("Bannir un utilisateur")
  .addUserOption((option) =>
    option
      .setName("utilisateur")
      .setDescription("L'utilisateur à bannir")
      .setRequired(true)
  )
  .addStringOption((option) =>
    option
      .setName("raison")
      .setDescription("La raison du bannissement (facultatif)")
      .setRequired(false)
  );

// Événement de commande
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isCommand()) return;

  if (interaction.commandName === "ban") {
    if (!interaction.memberPermissions.has(PermissionsBitField.Flags.BanMembers))
      return interaction.reply({
        content: "Vous n'avez pas la permission de bannir les utilisateurs.",
        ephemeral: true,
      });

    const user = interaction.options.getUser("utilisateur");
    const reason = interaction.options.getString("raison") || "Aucune raison fournie";

    try {
      await interaction.guild.members.ban(user, { reason });
      await interaction.reply({ content: `**${user.tag}** a été banni avec la raison : ${reason}`, ephemeral: true });
    } catch (err) {
      console.error(err);
      await interaction.reply({ content: "Une erreur est survenue lors du bannissement de l'utilisateur.", ephemeral: true });
    }
  }
});

// Connexion du bot Discord
client.on("ready", () => {
  console.log(`Bot Discord connecté en tant que ${client.user.tag}`);
});

// Chargement des commandes
client.on("ready", () => {
  client.application.commands.set({ application_id: client.user.id, commands: [banCommand] }).then(() => console.log("Commande de bannissement chargée avec succès."));
});

// Connexion du bot Discord
client.login(process.env.DISCORD_TOKEN);
```

4. Enregistrez le fichier, puis exécutez `node index.js` pour lancer le bot.

5. Cela devrait créer une commande slash `ban` pour votre bot, qui, lorsque utilisée, bannira l'utilisateur ciblé avec la raison fournie (ou pas).

6. Si vous souhaitez personnaliser davantage les boutons de confirmation et d'annulation, vous pouvez utiliser les objets `ActionRowBuilder` et `ButtonBuilder`, en remplaçant le code `interaction.reply` ci-dessus par le code suivant :

```javascript
const banButton = new ActionRowBuilder()
  .addComponents(
    new ButtonBuilder()
      .setCustomId("ban")
      .setLabel("Bannir")
      .setStyle(ButtonStyle.Danger)
  );

const cancelBtn = new ActionRowBuilder()
  .addComponents(
    new ButtonBuilder()
      .setCustomId("cancel")
      .setLabel("Annuler")
      .setStyle(ButtonStyle.Secondary)
  );

await interaction.reply({
  content: `Êtes-vous sûr de vouloir bannir **${user.tag}** ?`,
  ephemeral: true,
  components: [banButton, cancelBtn],
});
```

7. Ensuite, ajoutez les événements d'interaction pour traiter les réponses de bouton :

```javascript
client.on("interactionCreate", async (interaction) => {
  if (!interaction.isCommand()) return;

  if (interaction.commandName === "ban") {
    if (!interaction.memberPermissions.has(PermissionsBitField.Flags.BanMembers))
      return interaction.reply({
        content: "Vous n'avez pas la permission de bannir les utilisateurs.",
        ephemeral: true,
      });

    const user = interaction.options.getUser("utilisateur");
    const reason = interaction.options.getString("raison") || "Aucune raison fournie";

    if (interaction.customId === "ban") {
      try {
        await interaction.guild.members.ban(user, { reason });
        await interaction.editReply({
          content: `**${user.tag}** a été banni avec la raison : ${reason}`,
          components: [],
        });
      } catch (err) {
        console.error(err);
        await interaction.editReply({ content: "Une erreur est survenue lors du bannissement de l'utilisateur." });
      }
    } else if (interaction.customId === "cancel") {
      await interaction.editReply({ content: "Bannissement annulé", components: [] });
    }
  }
});
```

Cela devrait créer des boutons de confirmation et d'annulation pour le bannissement, ce qui peut améliorer l'expérience utilisateur. Remplacez `interaction.reply` par `interaction.editReply` pour que les réponses de bouton fonctionnent correctement.

Voici un cadre de test Cypress de haute qualité qui utilise Docker et utilise la capacité de Cypress à capturer des captures d'écran et à les enregistrer :

1. Créez un nouveau dossier de projet Cypress, puis exécutez `npm init -y` pour initialiser un nouveau projet.

2. Créez un nouveau fichier de configuration Cypress, nommé `cypress.json`, à la racine du projet. Ajoutez les propriétés suivantes :

```
{
  "baseUrl": "http://localhost:3000",
  "integrationFolder": "cypress/integration",
  "viewportHeight": 1080,
  "viewportWidth": 1920,
  "pageLoadTimeout": 10000,
  "defaultCommandTimeout": 5000,
  "reporter": "mocha-junit-reporter",
  "reporterOptions": {
    "mochaFile": "test-results.xml",
    "pageTitle": "Cypress Test Results"
  },
  "screenshotOnRunFailure": true,
  "video": false,
  "chromeWebSecurity": false,
  "experimentalInteractiveRun": true
}
```

3. Installez les dépendances Cypress en exécutant la commande suivante :

```
npm install cypress --save-dev
```

4. Installez `cypress-mocha`, `cypress-multi-reporters` et `cypress-docker-screenshot` en exécutant les commandes suivantes :

```
npm install cypress-mocha cypress-multi-reporters cypress-docker-screenshot --save-dev
```

5. Créez un nouveau dossier `cypress` dans le répertoire racine de votre projet. Créez les sous-dossiers suivants :

- `cypress/integration`
- `cypress/screenshots`
- `cypress/videos`

6. Créez un nouveau fichier de configuration de Cypress Docker, nommé `cypress.docker.config.js`, dans le répertoire `cypress` :

```
const { defineConfig } = require("cypress");

module.exports = defineConfig({
  e2e: {
    setupNodeEvents(on, config) {
      // run Cypress plugins here
    },
    baseUrl: "http://localhost:3000",
    video: false,
    screenshotOnRunFailure: true,
    chromeWebSecurity: false,
    experimentalInteractiveRun: true,
    reporter: "cypress-multi-reporters",
    reporters: require("cypress-multi-reporters").default,
    reporterOptions: {
      configFile: "cypress/reporter/multi-reporters.json"
    },
    env: {
      DOCKER_IMAGE: "node:14-alpine"
    },
    plugins: require("./plugins"),
    supportFile: "cypress/support/index.js"
  },
  component: {
    specPattern: "cypress/component/**/*.spec.js",
    pageObjectsPattern: "cypress/component/**/*.page.js",
    supportFile: false,
    retries: 0
  }
});
```

7. Créez un nouveau dossier `cypress/reporter` dans le répertoire racine de votre projet. Créez un nouveau fichier de configuration de Cypress multi-reporters, nommé `multi-reporters.json`, dans ce nouveau dossier :

```
{
  "reporterEnabled": "mocha-junit-reporter"
}
```

8. Créez un nouveau dossier `cypress/plugins` dans le répertoire racine de votre projet. Créez un nouveau fichier de configuration de Cypress, nommé `index.js`, dans ce nouveau dossier :

```
const { registerPlugin } = require("cypress");

const docker = require("cypress-docker-screenshot");

registerPlugin("screenshot", (on, config) => {
  on("task", {
    takeScreenshot: (title) => {
      return docker.takeScreenshot(title, config);
    }
  });
});
```

9. Créez un nouveau dossier `cypress/support` dans le répertoire racine de votre projet. Créez un nouveau fichier de support Cypress, nommé `index.js`, dans ce nouveau dossier :

```
const { defineSupportCode } = require("@cypress/support");

defineSupportCode(({ addCommand, addMatch, addMethod, addChainableCommand }) => {
  addChainableCommand(
    {
      getBrowser: () => cy.window().then((win) => win.navigator.userAgent),
    },
    { prevSubject: "option" }
  );

  addMethod("getBrowser", { prevSubject: "option" }, (subject, opts) => {
    return cy.wrap(subject).then((win) => win.navigator.userAgent);
  });

  addCommand("getBrowser", (subject, done) => {
    cy.window().then((win) => {
      done(null, win.navigator.userAgent);
    });
  });
});
```

10. Créez un nouveau dossier `cypress/component` dans le répertoire racine de votre projet. Créez un nouveau fichier de test Cypress, nommé `example.spec.js`, dans ce nouveau dossier :

```
describe("My Component", () => {
  it("should render", () => {
    cy.visit("index.html");
    cy.title().should("contain", "My Component");
    cy.get("h1").should("contain", "My Component");
    cy.get("img").should("have.attr", "src", "/logo.png");
    cy.get("a").should("have.attr", "href", "/link");
    cy.getBrowser().should("include", "Cypress");
  });
});
```

11. Créez un nouveau dossier `cypress/component/page-objects` dans le répertoire racine de votre projet. Créez un nouveau fichier de page objet Cypress, nommé `example.page.js`, dans ce nouveau dossier :

```
class ExamplePage {
  visit() {
    cy.visit("index.html");
  }

  getHeading() {
    return cy.get("h1");
  }

  getLogo() {
    return cy.get("img");
  }

  getLink() {
    return cy.get("a");
  }

  getBrowser() {
    return cy.getBrowser();
  }
}

export default new ExamplePage();
```

12. Créez un nouveau dossier `cypress/component` dans le répertoire racine de votre projet. Créez un nouveau fichier de configuration de Cypress, nommé `cypress.json`, à la racine de ce nouveau dossier. Ajoutez les propriétés suivantes :

```
{
  "baseUrl": "/",
  "viewportHeight": 1080,
  "viewportWidth": 1920,
  "pageLoadTimeout": 10000,
  "defaultCommandTimeout": 5000,
  "reporter": "mocha-junit-reporter",
  "reporterOptions": {
    "mochaFile": "test-results.xml",
    "pageTitle": "Cypress Component Test Results"
  },
  "screenshotOnRunFailure": true,
  "video": false,
  "chromeWebSecurity": false,
  "experimentalInteractiveRun": true
}
```

13. Dans le dossier de votre projet, exécutez la commande suivante pour lancer Cypress dans le conteneur Docker :

```
docker run --rm -v $(pwd):/app -w /app -u $(id -u):$(id -g) -e Cypress_baseUrl=http://localhost:3000 -e Cypress_video=false -e Cypress_screenshotOnRunFailure=true -e Cypress_chromeWebSecurity=false -e Cypress_experimentalInteractiveRun=true -e Cypress_docker=true -e Cypress_docker_screenshot=true -e Cypress_docker_image=node:14-alpine cypress/base:14.16.0 /bin/sh -c "cypress run"
```

Cela exécutera Cypress en tant que conteneur Docker, en chargeant le projet Cypress dans le conteneur et en exécutant les tests Cypress. Les captures d'écran de la dernière étape de chaque échec de test seront enregistrées dans le dossier `cypress/screenshots` dans le conteneur Docker. Les résultats des tests seront enregistrés dans le fichier `test-results.xml` dans le dossier `cypress` de votre projet. En plus de cela, les captures d'écran seront générées en tant que tâches Docker, ce qui signifie que vous pouvez les consulter dans le portail Docker, si vous souhaitez les visualiser en plus de celles enregistrées dans le conteneur.

Remarque : Assurez-vous de remplacer `http://localhost:3000` avec le serveur de test local approprié pour votre projet. Si vous utilisez un autre serveur de test local, assurez-vous de le remplacer dans le fichier de configuration Cypress, les environnements Docker et les commandes de ligne de commande.

