    {"ol", "ol"},
    {"li", "li"},
    {"br", "br"},
    {"a", "a"},
    {"img", "img"},
    {"table", "table"},
    {"thead", "thead"},
    {"tbody", "tbody"},
    {"tr", "tr"},
    {"th", "th"},
    {"td", "td"},
    {"hr", "hr"},
};

std::string convertirMarkdownEnHtml(const std::string& markdown) {
    // Créer un moteur Puglind
    pugl::pugl puglind;

    // Compiler le moteur Puglind avec le tableau de correspondances de balises HTML
    puglind.compilateur(puglind_html_tags);

    // Compiler le texte Markdown en HTML
    std::string html = pugl::to_html(markdown);

    // Retourner le texte HTML
    return html;
}
