\begin{document}

% Exemple d'utilisation de la notation FEN
\fenboard{rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR}

% Exemple d'utilisation de la notation aléatoire
\fennotation{rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR}

\end{document}
